import * as Sentry from "@sentry/node";
import { isProductionLike } from "@foundation/config";
import { Hono } from "hono";
import { cors } from "hono/cors";
import { logger } from "hono/logger";
import { secureHeaders } from "hono/secure-headers";
import { bodyLimit } from "hono/body-limit";
import { socialAuthRoute } from "./routes/auth-social";
import { entitlementsRoute } from "./routes/me-entitlements";
import { emailPreferencesRoute } from "./routes/me-email-preferences";
import { onboardingRoute } from "./routes/me-onboarding";
import { deleteAccountRoute } from "./routes/me-delete";
import { revenueCatWebhookRoute } from "./routes/revenuecat-webhook";
import { stripeRoute } from "./routes/me-stripe";
import { globalRateLimit, authRateLimit, webhookRateLimit } from "./middleware/rate-limit";
import { verifyCloudflareOrigin } from "./middleware/cloudflare-origin";
import { getServerEnv } from "./lib/env";

const app = new Hono();

const { runtime } = getServerEnv();

// 1. Security headers (outermost — applies to all responses including errors)
app.use("*", secureHeaders({
  contentSecurityPolicy: { defaultSrc: ["'none'"] },
  crossOriginResourcePolicy: "same-origin",
}));

// 2. CORS — restrict to configured origin
app.use("*", cors({
  origin: runtime.appOrigin,
  allowMethods: ["GET", "POST", "PATCH", "DELETE"],
  allowHeaders: ["Authorization", "Content-Type"],
  maxAge: 86400,
}));

// 3. Body size limit — block oversized payloads before parsing
app.use("*", bodyLimit({
  maxSize: 100 * 1024,
  onError: (c) => c.json({ error: "Request body too large" }, 413),
}));

// 4. Request logging
app.use("*", logger());

// 5. Global rate limit
app.use("*", globalRateLimit);

// 6. Cloudflare origin verification (production + staging) — /api/* only so health probes pass unauthenticated
if (isProductionLike(runtime.appEnv) && runtime.cfVerifySecret) {
  app.use("/api/*", verifyCloudflareOrigin(runtime.cfVerifySecret));
}

app.onError((err, c) => {
  Sentry.captureException(err);
  console.error(`[ERROR] ${c.req.method} ${c.req.path}:`, err.message);
  return c.json({ error: "Internal server error" }, 500);
});

app.get("/health", (c) => c.json({ status: "ok" }));

// Per-route rate limits
app.use("/api/auth/*", authRateLimit);
app.use("/api/me/checkout-session", authRateLimit);
app.use("/api/me/billing-portal", authRateLimit);
app.use("/api/revenuecat/*", webhookRateLimit);

app.route("/api/auth", socialAuthRoute);
app.route("/api/me", entitlementsRoute);
app.route("/api/me", emailPreferencesRoute);
app.route("/api/me", onboardingRoute);
app.route("/api/me", deleteAccountRoute);
app.route("/api/me", stripeRoute);
app.route("/api/revenuecat", revenueCatWebhookRoute);

export { app };

