describe("entitlements handler", () => {
  const subscriberWithEntitlements: RevenueCatCustomerInfo = {
    items: [
      {
        id: "sub_1",
        product_id: "plant_monthly",
        store: "app_store",
        status: "active",
        gives_access: true,
        entitlements: { items: [{ id: "ent_1", lookup_key: "plant_id_pro", display_name: "Plant ID Pro" }], next_page: null },
        current_period_ends_at: null
      },
      {
        id: "sub_2",
        product_id: "all_apps_bundle",
        store: "app_store",
        status: "active",
        gives_access: true,
        entitlements: { items: [{ id: "ent_2", lookup_key: "bird_id_pro", display_name: "Bird ID Pro" }], next_page: null },
        current_period_ends_at: null
      }
    ]
  };

  function entitlementsDeps(user: AppUser | null, customerInfo: RevenueCatCustomerInfo | null = null) {
    const cache = new MemorySubscriberCache();
    if (user && customerInfo) cache.cache.set(user.id, mapAllEntitlements(customerInfo));
    return { auth: auth(user), subscriptions: cache };
  }

  it("should return 401 when not authenticated", async () => {
    const result = await handleGetEntitlements({ headers: {} }, entitlementsDeps(null));
    expect(result.status).toBe(401);
  });

  it("should return empty maps when user has no subscription data", async () => {
    const result = await handleGetEntitlements({ headers: {} }, entitlementsDeps({ id: "user-1", email: null }));
    expect(result).toEqual({ status: 200, body: { real: {}, virtual: {}, snapshots: [], effectiveForApp: null } });
  });

  it("should return real entitlements from cached subscriber snapshot", async () => {
    const user = { id: "user-1", email: "u@test.com" };
    const result = await handleGetEntitlements({ headers: {} }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(200);
    const body = result.body as { real: Record<string, boolean>; virtual: Record<string, boolean>; effectiveForApp: unknown };
    expect(body.real).toEqual({ plant_id_pro: true, bird_id_pro: true });
    expect(body.virtual).toEqual({});
    expect(body.effectiveForApp).toBeNull();
  });

  it("should reject unknown app param", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlements({ headers: {}, query: { app: "appZ" } }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(400);
  });

  it("should compute virtual entitlements via cross-promo policy and filter by app", async () => {
    const user = { id: "user-1", email: null };
    const deps = {
      ...entitlementsDeps(user, subscriberWithEntitlements),
      crossPromoPolicy: { plant_id_pro: ["bonus_appB"] }
    };
    const result = await handleGetEntitlements({ headers: {}, query: { app: "appB" } }, deps);
    expect(result.status).toBe(200);
    const body = result.body as { real: Record<string, boolean>; virtual: Record<string, boolean>; effectiveForApp: Record<string, boolean> };
    expect(body.virtual).toEqual({ bonus_appB: true });
    expect(body.effectiveForApp).toEqual({ bonus_appB: true });
  });

  it("should return specific entitlement by id", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlement("plant_id_pro", { headers: {} }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(200);
    expect((result.body as { entitlementId: string }).entitlementId).toBe("plant_id_pro");
  });

  it("should return 404 for unknown entitlement id", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlement("unknown", { headers: {} }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(404);
  });

  it("should return 404 when user has no cached data and specific entitlement requested", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlement("pro", { headers: {} }, entitlementsDeps(user));
    expect(result.status).toBe(404);
  });

  it("should return 401 for specific entitlement when not authenticated", async () => {
    const result = await handleGetEntitlement("pro", { headers: {} }, entitlementsDeps(null));
    expect(result.status).toBe(401);
  });
});

