describe("checkout session handler", () => {
  const user = { id: "user-1", email: "u@test.com" };
  const validBody = {
    appId: "appA",
    priceId: "price_abc123",
    successUrl: "https://app.example.com/success",
    cancelUrl: "https://app.example.com/cancel",
  };

  function checkoutDeps(
    u: AppUser | null,
    overrides: { customers?: StripeCustomerStore; stripe?: StripeClient } = {}
  ) {
    return {
      auth: auth(u),
      customers: overrides.customers ?? new MemoryStripeCustomerStore(),
      stripe: overrides.stripe ?? new MemoryStripeClient(),
    };
  }

  it("should return 401 when not authenticated", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: validBody },
      checkoutDeps(null)
    );
    expect(result.status).toBe(401);
  });

  it("should return 400 for invalid priceId", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, priceId: "invalid" } },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
    expect((result.body as Record<string, unknown>).error).toContain("priceId");
  });

  it("should return 400 for missing priceId", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: { appId: "appA", successUrl: validBody.successUrl, cancelUrl: validBody.cancelUrl } },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
  });

  it("should return 400 for unknown appId", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, appId: "appZ" } },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
    expect((result.body as Record<string, unknown>).error).toContain("appId");
  });

  it("should return 400 for missing appId", async () => {
    const { appId: _ignored, ...rest } = validBody;
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: rest },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
  });

  it("should reject http successUrl except localhost", async () => {
    const reject = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, successUrl: "http://app.example.com/success" } },
      checkoutDeps(user)
    );
    expect(reject.status).toBe(400);

    const accept = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, successUrl: "http://localhost:3000/success", cancelUrl: "http://127.0.0.1:3000/cancel" } },
      checkoutDeps(user)
    );
    expect(accept.status).toBe(200);
  });

  it("should reject http cancelUrl except localhost", async () => {
    const reject = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, cancelUrl: "http://app.example.com/cancel" } },
      checkoutDeps(user)
    );
    expect(reject.status).toBe(400);

    const accept = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, cancelUrl: "http://localhost:3000/cancel" } },
      checkoutDeps(user)
    );
    expect(accept.status).toBe(200);
  });

  it("should return 400 for invalid successUrl", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, successUrl: "not-a-url" } },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
    expect((result.body as Record<string, unknown>).error).toContain("successUrl");
  });

  it.each([
    ["ftp://app.example.com/success"],
    ["javascript:alert(1)"],
    ["data:text/html,<script>alert(1)</script>"],
    ["//app.example.com/success"],
    ["file:///etc/passwd"],
  ])("should reject unsafe successUrl scheme: %s", async (successUrl) => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, successUrl } },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
    expect((result.body as Record<string, unknown>).error).toContain("successUrl");
  });

  it("should return 400 for invalid cancelUrl", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: { ...validBody, cancelUrl: "" } },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
    expect((result.body as Record<string, unknown>).error).toContain("cancelUrl");
  });

  it("should create Stripe customer when none exists and return checkout URL", async () => {
    const customers = new MemoryStripeCustomerStore();
    const stripe = new MemoryStripeClient();
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: validBody },
      checkoutDeps(user, { customers, stripe })
    );
    expect(result.status).toBe(200);
    expect((result.body as Record<string, unknown>).checkoutUrl).toBe("https://checkout.stripe.com/session_123");
    expect(stripe.createdCustomers).toHaveLength(1);
    expect(stripe.createdCustomers[0].email).toBe("u@test.com");
    expect(customers.customers.get("user-1")).toBe("cus_1");
    expect(stripe.createdCheckouts).toHaveLength(1);
    expect(stripe.createdCheckouts[0]).toMatchObject({
      customerId: "cus_1",
      priceId: "price_abc123",
      clientReferenceId: "user-1",
      metadata: { app_user_id: "user-1", supabase_user_id: "user-1", app_id: "appA" },
      subscriptionMetadata: { app_user_id: "user-1", supabase_user_id: "user-1", app_id: "appA" },
    });
    expect(stripe.createdCustomers[0].metadata).toMatchObject({
      app_user_id: "user-1",
      supabase_user_id: "user-1",
      app_id: "appA",
    });
  });

  it("should reuse existing Stripe customer and sync email", async () => {
    const customers = new MemoryStripeCustomerStore();
    customers.customers.set("user-1", "cus_existing");
    const stripe = new MemoryStripeClient();
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: validBody },
      checkoutDeps(user, { customers, stripe })
    );
    expect(result.status).toBe(200);
    expect(stripe.createdCustomers).toHaveLength(0);
    expect(stripe.emailUpdates).toEqual([{ customerId: "cus_existing", email: "u@test.com" }]);
    expect(stripe.createdCheckouts[0]).toMatchObject({ customerId: "cus_existing" });
  });

  it("should skip email sync when reusing customer with no email on user", async () => {
    const customers = new MemoryStripeCustomerStore();
    customers.customers.set("user-2", "cus_existing");
    const stripe = new MemoryStripeClient();
    await handleCreateCheckoutSession(
      { headers: {}, body: validBody },
      checkoutDeps({ id: "user-2", email: null }, { customers, stripe })
    );
    expect(stripe.emailUpdates).toHaveLength(0);
  });

  it("should handle user with null email for customer creation", async () => {
    const stripe = new MemoryStripeClient();
    await handleCreateCheckoutSession(
      { headers: {}, body: validBody },
      checkoutDeps({ id: "user-2", email: null }, { stripe })
    );
    expect(stripe.createdCustomers[0].email).toBeNull();
  });

  it("should return 400 for null body", async () => {
    const result = await handleCreateCheckoutSession(
      { headers: {}, body: null },
      checkoutDeps(user)
    );
    expect(result.status).toBe(400);
  });
});

