    if (user && completed.length > 0) {
      store.completed.set(user.id, new Set(completed));
    }
    return { auth: auth(user), onboarding: store };
  }

  it("should return 401 when not authenticated (GET)", async () => {
    const result = await handleGetOnboarding(onboardingDeps(null));
    expect(result.status).toBe(401);
  });

  it("should return all apps as false for a new user", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetOnboarding(onboardingDeps(user));
    expect(result.status).toBe(200);
    expect(result.body).toEqual({ appA: false, appB: false });
  });

  it("should reflect completed apps", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetOnboarding(onboardingDeps(user, ["appA"]));
    expect(result.status).toBe(200);
    expect(result.body).toEqual({ appA: true, appB: false });
  });

  it("should return 401 when not authenticated (PATCH)", async () => {
    const result = await handleCompleteOnboarding("appA", onboardingDeps(null));
    expect(result.status).toBe(401);
  });

  it("should return 400 for an unknown appId", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleCompleteOnboarding("unknown-app", onboardingDeps(user));
    expect(result.status).toBe(400);
  });

  it("should mark the app complete and return full state", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleCompleteOnboarding("appA", onboardingDeps(user));
    expect(result.status).toBe(200);
    expect(result.body).toEqual({ appA: true, appB: false });
  });

  it("should be idempotent when completing the same app twice", async () => {
    const user = { id: "user-1", email: null };
    const deps = onboardingDeps(user, ["appA"]);
    const result = await handleCompleteOnboarding("appA", deps);
    expect(result.status).toBe(200);
    expect(result.body).toEqual({ appA: true, appB: false });
  });

  it("should track multiple apps independently", async () => {
    const user = { id: "user-1", email: null };
    const deps = onboardingDeps(user);
    await handleCompleteOnboarding("appA", deps);
    const result = await handleCompleteOnboarding("appB", deps);
    expect(result.status).toBe(200);
    expect(result.body).toEqual({ appA: true, appB: true });
  });
});

