import { isAppId } from "@foundation/config";
import type { AppResponse, AuthReader, UserOnboardingStore } from "./types";

export interface OnboardingDeps {
  auth: AuthReader;
  onboarding: UserOnboardingStore;
}

export async function handleGetOnboarding(deps: OnboardingDeps): Promise<AppResponse> {
  const user = await deps.auth.getUser();
  if (!user) return { status: 401, body: { error: "Authentication required" } };
  const status = await deps.onboarding.getByUserId(user.id);
  return { status: 200, body: status };
}

export async function handleCompleteOnboarding(appId: string, deps: OnboardingDeps): Promise<AppResponse> {
  const user = await deps.auth.getUser();
  if (!user) return { status: 401, body: { error: "Authentication required" } };
  if (!isAppId(appId)) return { status: 400, body: { error: `Unknown app: ${appId}` } };
  await deps.onboarding.complete(user.id, appId);
  const status = await deps.onboarding.getByUserId(user.id);
  return { status: 200, body: status };
}

