  rcEntitlementId?: string;
}

export interface StripeCustomerStore {
  findByUserId(userId: string): Promise<string | null>;
  upsert(userId: string, stripeCustomerId: string): Promise<void>;
}

export interface StripeClient {
  createCustomer(email: string | null, metadata: Record<string, string>): Promise<string>;
  updateCustomerEmail(customerId: string, email: string): Promise<void>;
  createCheckoutSession(params: {
    customerId: string;
    priceId: string;
    successUrl: string;
    cancelUrl: string;
    clientReferenceId: string;
    metadata: Record<string, string>;
    subscriptionMetadata: Record<string, string>;
  }): Promise<string>;
  createBillingPortalSession(params: {
    customerId: string;
    returnUrl: string;
  }): Promise<string>;
}

export interface CheckoutSessionDeps {
  auth: AuthReader;
  customers: StripeCustomerStore;
  stripe: StripeClient;
}

export interface BillingPortalDeps {
  auth: AuthReader;
  revenueCat: RevenueCatManagementClient;
}

