import * as Sentry from "@sentry/node";
import Stripe from "stripe";
import type {
  AppUser,
  AuthReader,
  BillingEventStore,
  DeviceInfo,
  DeviceStore,
  EmailPreferences,
  EmailPreferencesStore,
  RevenueCatClient,
  RevenueCatManagementClient,
  RevenueCatWebhookDeps,
  StripeClient,
  StripeCustomerStore,
  SubscriberCacheStore,
  UserDeleter,
  UserDirectory,
  UserOnboardingStore
} from "@/lib/api/types";
import type { RevenueCatCustomerInfo } from "@foundation/config";
import { APPS, mapAllEntitlements, type EntitlementSnapshot, type SubscriptionStatus } from "@foundation/config";
import { isValidUuid } from "@/lib/api/social-auth";
import { createSupabaseClientFromToken, createSupabaseServiceClient } from "./server";
import { getServerEnv } from "@/lib/env";

function reportDbError(error: { message: string }, context: string, message: string, extra?: Record<string, unknown>): void {
  Sentry.captureException(error, { extra: { context, ...extra } });
  console.error(`[${context}] ${message}:`, error.message);
}

export function createAuthReader(token: string): AuthReader {
  return {
    async getUser(): Promise<AppUser | null> {
      const supabase = createSupabaseClientFromToken(token);
      const { data, error } = await supabase.auth.getUser();
      if (error || !data.user) return null;
      return { id: data.user.id, email: data.user.email ?? null };
    }
  };
}

export function createUserDirectory(): UserDirectory {
  return {
    async findExistingUserId(candidates: string[]): Promise<string | null> {
      const userId = candidates.find(c => isValidUuid(c));
      if (!userId) return null;
      const supabase = createSupabaseServiceClient();
      const { data, error } = await supabase.auth.admin.getUserById(userId);
      if (error) {
        reportDbError(error, "findExistingUserId", "Supabase admin lookup failed", { userId });
        return null;
      }
      return data.user?.id ?? null;
    }
  };
}

export function createBillingEventStore(): BillingEventStore {
  return {
    async hasProcessed(eventId: string): Promise<boolean> {
      const supabase = createSupabaseServiceClient();
      const { data, error } = await supabase.from("billing_events").select("event_id").eq("event_id", eventId).maybeSingle();
      if (error) {
        reportDbError(error, "billing_events.hasProcessed", "hasProcessed query failed", { eventId });
      }
      return !!data;
    },
    async record(input: { eventId: string; userId: string | null; apiVersion: string | null }): Promise<void> {
      const supabase = createSupabaseServiceClient();
      const { error } = await supabase.from("billing_events").insert({
        event_id: input.eventId,
        user_id: input.userId,
        event_type: input.eventId,
        api_version: input.apiVersion,
      });
      if (error) {
        reportDbError(error, "billing_events.record", "Insert failed", { eventId: input.eventId });
      }
    }
  };
}

export function createSubscriberCacheStore(): SubscriberCacheStore {
  return {
    async upsert(userId: string, customerInfo: RevenueCatCustomerInfo): Promise<void> {
      const supabase = createSupabaseServiceClient();
      const snapshots = mapAllEntitlements(customerInfo);
      const now = new Date().toISOString();
      const { error: deleteError } = await supabase
        .from("user_entitlements").delete().eq("user_id", userId);
      if (deleteError) {
        reportDbError(deleteError, "user_entitlements.upsert", "Delete failed", { userId });
        return;
      }
      if (snapshots.length === 0) return;
      const { error } = await supabase.from("user_entitlements").insert(
        snapshots.map((snap: EntitlementSnapshot) => ({
          user_id: userId,
          entitlement_id: snap.entitlementId,
          status: snap.status,
          product_identifier: snap.productIdentifier ?? null,
          store: snap.store,
          expires_at: snap.expiresAt ?? null,
          last_synced_at: now,
        }))
      );
      if (error) {
        reportDbError(error, "user_entitlements.upsert", "Insert failed", { userId });
      }
    },
    async getByUserId(userId: string): Promise<EntitlementSnapshot[]> {
      const supabase = createSupabaseServiceClient();
      const { data, error } = await supabase
        .from("user_entitlements")
        .select("entitlement_id, status, product_identifier, store, expires_at")
        .eq("user_id", userId);
      if (error) {
        reportDbError(error, "user_entitlements.getByUserId", "Query failed", { userId });
        return [];
      }
      return (data ?? []).map((row) => ({
        entitlementId: row.entitlement_id,
        status: row.status as SubscriptionStatus,
        productIdentifier: row.product_identifier,
        store: row.store,
        expiresAt: row.expires_at,
      }));
    }
  };
}

export function createEmailPreferencesStore(): EmailPreferencesStore {
  return {
    async getByUserId(userId: string): Promise<EmailPreferences | null> {
      const supabase = createSupabaseServiceClient();
      const { data, error } = await supabase
        .from("email_preferences")
        .select("marketing, product_updates, transactional")
        .eq("user_id", userId)
        .maybeSingle();
      if (error) {
        reportDbError(error, "email_preferences.getByUserId", "Query failed", { userId });
        return null;
      }
      if (!data) return null;
      return { marketing: data.marketing, productUpdates: data.product_updates, transactional: data.transactional };
    },
    async update(userId: string, patch: Partial<EmailPreferences>): Promise<EmailPreferences> {
      const supabase = createSupabaseServiceClient();
      const dbPatch: Record<string, boolean> = {};
      if (patch.marketing !== undefined) dbPatch.marketing = patch.marketing;
      if (patch.productUpdates !== undefined) dbPatch.product_updates = patch.productUpdates;
      if (patch.transactional !== undefined) dbPatch.transactional = patch.transactional;
      const { data, error } = await supabase
        .from("email_preferences")
        .update(dbPatch)
        .eq("user_id", userId)
        .select("marketing, product_updates, transactional")
        .single();
      if (error) {
        reportDbError(error, "email_preferences.update", "Update failed", { userId });
        throw new Error(`email_preferences update failed: ${error.message}`);
      }
      return { marketing: data.marketing, productUpdates: data.product_updates, transactional: data.transactional };
    }
  };
}

export function createUserOnboardingStore(): UserOnboardingStore {
  return {
    async getByUserId(userId: string): Promise<Record<string, boolean>> {
      const supabase = createSupabaseServiceClient();
      const { data, error } = await supabase
        .from("user_onboarding")
        .select("app_id")
        .eq("user_id", userId)
        .not("completed_at", "is", null);
      if (error) {
        reportDbError(error, "user_onboarding.getByUserId", "Query failed", { userId });
        throw new Error(`user_onboarding query failed: ${error.message}`);
      }
      const completed = new Set((data ?? []).map((r) => r.app_id as string));
      return Object.fromEntries(APPS.map((app) => [app, completed.has(app)]));
    },
    async complete(userId: string, appId: string): Promise<void> {
      const supabase = createSupabaseServiceClient();
      const { error } = await supabase.from("user_onboarding").upsert(
        { user_id: userId, app_id: appId, completed_at: new Date().toISOString() },
        { onConflict: "user_id,app_id" }
      );
      if (error) {
        reportDbError(error, "user_onboarding.complete", "Upsert failed", { userId, appId });
        throw new Error(`user_onboarding upsert failed: ${error.message}`);
      }
    }
  };
}

export function createUserDeleter(): UserDeleter {
  return {
    async deleteById(userId: string): Promise<void> {
      const supabase = createSupabaseServiceClient();
      const { error } = await supabase.auth.admin.deleteUser(userId);
      if (error) {
        reportDbError(error, "users.deleteById", "Delete failed", { userId });
        throw new Error(`User deletion failed: ${error.message}`);
      }
    }
  };
}

export function createDeviceStore(): DeviceStore {
  return {
    async upsert(userId: string, device: DeviceInfo): Promise<void> {
      const supabase = createSupabaseServiceClient();
      const { error } = await supabase.from("user_devices").upsert(
        {
          device_id: device.device_id,
          user_id: userId,
          platform: device.platform,
          device_name: device.device_name ?? null,
          last_seen_at: new Date().toISOString()
        },
        { onConflict: "device_id,user_id" }
      );
      if (error) {
        reportDbError(error, "user_devices.upsert", "Upsert failed", { userId });
      }
    },
    async countByUserId(userId: string): Promise<number> {
      const supabase = createSupabaseServiceClient();
      const { count, error } = await supabase
        .from("user_devices")
        .select("*", { count: "exact", head: true })
        .eq("user_id", userId);
      if (error) {
        reportDbError(error, "user_devices.count", "Count query failed", { userId });
      }
      return count ?? 0;
    }
  };
}

export function createRevenueCatClient(): RevenueCatClient & RevenueCatManagementClient {
  return {
    async fetchCustomerInfo(userId: string): Promise<RevenueCatCustomerInfo> {
      const { revenueCatSecretApiKey, revenueCatProjectId } = getServerEnv();
      const url = `https://api.revenuecat.com/v2/projects/${encodeURIComponent(revenueCatProjectId)}/customers/${encodeURIComponent(userId)}/subscriptions`;
      const response = await fetch(url, {
        headers: { Authorization: `Bearer ${revenueCatSecretApiKey}` }
      });
      if (!response.ok) {
        const body = await response.text();
        console.error("[revenuecat] fetchCustomerInfo failed:", response.status, body);
        const err = new Error(`RevenueCat request failed: ${response.status}`);
        Sentry.captureException(err, { extra: { context: "revenuecat.fetchCustomerInfo", userId, status: response.status, body } });
        throw err;
      }
      return response.json();
    },

    async fetchManagementUrl(userId: string): Promise<string | null> {
      const { revenueCatSecretApiKey, revenueCatProjectId } = getServerEnv();
      const headers = { Authorization: `Bearer ${revenueCatSecretApiKey}` };

      const listUrl = `https://api.revenuecat.com/v2/projects/${encodeURIComponent(revenueCatProjectId)}/customers/${encodeURIComponent(userId)}/subscriptions`;
      const listResponse = await fetch(listUrl, { headers });
      const listBody = await listResponse.text();

      if (!listResponse.ok) {
        if (listResponse.status === 404) {
          console.log(`[revenuecat] fetchManagementUrl userId=${userId} status=404 (not found)`);
          return null;
        }
        console.error("[revenuecat] fetchManagementUrl list failed:", listResponse.status, listBody);
        const err = new Error(`RevenueCat request failed: ${listResponse.status}`);
        Sentry.captureException(err, { extra: { context: "revenuecat.fetchManagementUrl.list", userId, status: listResponse.status, body: listBody } });
        throw err;
      }

      const data = JSON.parse(listBody) as { items: Array<{ id: string; management_url?: string | null; gives_access?: boolean }> };
      const activeSub = data.items.find(s => s.gives_access);

      if (!activeSub) {
        console.log(`[revenuecat] fetchManagementUrl userId=${userId} no active subscription`);
        return null;
      }

      if (activeSub.management_url) {
        console.log(`[revenuecat] fetchManagementUrl userId=${userId} found static url`);
        return activeSub.management_url;
      }

      // RC only populates management_url statically for App Store / Play Store.
      // For Stripe Web Billing it is always null, and the dedicated endpoint also returns null for sandbox subs.
      // In production it generates an authenticated management link on demand.
      const mgmtUrl = `https://api.revenuecat.com/v2/projects/${encodeURIComponent(revenueCatProjectId)}/customers/${encodeURIComponent(userId)}/subscriptions/${encodeURIComponent(activeSub.id)}/actions/management_url`;
      const mgmtResponse = await fetch(mgmtUrl, { headers });
      const mgmtBody = await mgmtResponse.text();

      if (!mgmtResponse.ok) {
        if (mgmtResponse.status === 404) {
          console.log(`[revenuecat] fetchManagementUrl userId=${userId} subId=${activeSub.id} management_url endpoint 404`);
          return null;
        }
        console.error("[revenuecat] fetchManagementUrl mgmt failed:", mgmtResponse.status, mgmtBody);
        const err = new Error(`RevenueCat management_url request failed: ${mgmtResponse.status}`);
        Sentry.captureException(err, { extra: { context: "revenuecat.fetchManagementUrl.mgmt", userId, subId: activeSub.id, status: mgmtResponse.status, body: mgmtBody } });
        throw err;
      }

      const mgmtData = JSON.parse(mgmtBody) as { management_url: string | null };
      console.log(`[revenuecat] fetchManagementUrl userId=${userId} subId=${activeSub.id} found=${mgmtData.management_url !== null}`);
      return mgmtData.management_url ?? null;
    }
  };
}

export function createRevenueCatWebhookDeps(): RevenueCatWebhookDeps {
  const { runtime } = getServerEnv();
  return {
    expectedAuthorization: runtime.revenueCatWebhookAuthorization,
    events: createBillingEventStore(),
    users: createUserDirectory(),
    revenueCat: createRevenueCatClient(),
    subscriptions: createSubscriberCacheStore()
  };
}

export function createStripeCustomerStore(): StripeCustomerStore {
  return {
    async findByUserId(userId: string): Promise<string | null> {
      const supabase = createSupabaseServiceClient();
      const { data, error } = await supabase
        .from("stripe_customers")
        .select("stripe_customer_id")
        .eq("user_id", userId)
        .maybeSingle();
      if (error) {
        reportDbError(error, "stripe_customers.findByUserId", "Query failed", { userId });
      }
      return data?.stripe_customer_id ?? null;
    },
    async upsert(userId: string, stripeCustomerId: string): Promise<void> {
      const supabase = createSupabaseServiceClient();
      const { error } = await supabase.from("stripe_customers").upsert(
        {
          user_id: userId,
          stripe_customer_id: stripeCustomerId,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "user_id", ignoreDuplicates: false }
      );
      if (error) {
        reportDbError(error, "stripe_customers.upsert", "Upsert failed", { userId });
        throw new Error(`stripe_customers upsert failed: ${error.message}`, {
          cause: error,
        });
      }
    },
  };
}

export function createStripeClient(): StripeClient {
  const { runtime } = getServerEnv();
  const stripe = new Stripe(runtime.stripeSecretKey, {
    apiVersion: "2026-04-22.dahlia",
    appInfo: { name: "user-management", version: "0.1.0" },
  });
  return {
    async createCustomer(email: string | null, metadata: Record<string, string>): Promise<string> {
      const customer = await stripe.customers.create(
        email ? { email, metadata } : { metadata },
        { idempotencyKey: crypto.randomUUID() }
      );
      return customer.id;
    },
    async updateCustomerEmail(customerId: string, email: string): Promise<void> {
      await stripe.customers.update(customerId, { email });
    },
    async createCheckoutSession(params): Promise<string> {
      const session = await stripe.checkout.sessions.create(
        {
          customer: params.customerId,
          client_reference_id: params.clientReferenceId,
          mode: "subscription",
          line_items: [{ price: params.priceId, quantity: 1 }],
          success_url: params.successUrl,
          cancel_url: params.cancelUrl,
          allow_promotion_codes: true,
          billing_address_collection: "auto",
          customer_update: { address: "auto", name: "auto" },
          metadata: params.metadata,
          subscription_data: { metadata: params.subscriptionMetadata },
          ...(runtime.stripeAutomaticTax ? { automatic_tax: { enabled: true } } : {}),
        },
        { idempotencyKey: crypto.randomUUID() }
      );
      if (!session.url) {
        throw new Error("Stripe Checkout Session returned no URL");
      }
      return session.url;
    },
    async createBillingPortalSession(params): Promise<string> {
      const session = await stripe.billingPortal.sessions.create(
        {
          customer: params.customerId,
          return_url: params.returnUrl,
        },
        { idempotencyKey: crypto.randomUUID() }
      );
      return session.url;
    },
  };
}

