import { Hono } from "hono";
import { handleGetOnboarding, handleCompleteOnboarding } from "../lib/api/onboarding";
import { createAuthReader, createUserOnboardingStore } from "../lib/supabase/repositories";
import { getBearerToken } from "../lib/api/request";

const onboardingRoute = new Hono();

onboardingRoute.get("/onboarding", async (c) => {
  const token = getBearerToken(c);
  const result = await handleGetOnboarding({
    auth: createAuthReader(token),
    onboarding: createUserOnboardingStore(),
  });
  return c.json(result.body, result.status as never);
});

onboardingRoute.patch("/onboarding/:appId", async (c) => {
  const appId = c.req.param("appId");
  const token = getBearerToken(c);
  const result = await handleCompleteOnboarding(appId, {
    auth: createAuthReader(token),
    onboarding: createUserOnboardingStore(),
  });
  return c.json(result.body, result.status as never);
});

export { onboardingRoute };

create table public.user_onboarding (
  user_id      uuid        not null references auth.users(id) on delete cascade,
  app_id       text        not null,
  completed_at timestamptz,
  created_at   timestamptz not null default now(),
  primary key (user_id, app_id)
);

alter table public.user_onboarding enable row level security;

create policy "Users can read own onboarding"
  on public.user_onboarding for select
  using (auth.uid() = user_id);

create policy "Users can insert own onboarding"
  on public.user_onboarding for insert
  with check (auth.uid() = user_id);

create policy "Users can update own onboarding"
